static int cavern_guard_active(void){return cavern_phase(ex.phase)||(ex.entryY&&cavern_phase(ex.oldPhase));}
static int cavern_interval(float y,float radius,int side,float*left,float*right){float l=-100000,r=100000;for(int n=0;n<=(int)ceilf(radius*2);n++){float dy=fminf(radius,-radius+n),rx=sqrtf(fmaxf(0,radius*radius-dy*dy))+2;int yy=(int)floorf(y+dy),il,ir;l=fmaxf(l,tunnel_left(yy)+rx);r=fminf(r,tunnel_right(yy)-rx);if(tunnel_island(yy,&il,&ir)){if(side)l=fmaxf(l,ir+rx);else r=fminf(r,il-rx);}else if(!ex.giant.active&&!ex.bossWarning&&!ex.bossSpawned&&(!custom_environment()||journey_kind()==ENV_CRYSTAL)){/* Keep a chosen branch while an island tapers in or out. */if(side)l=fmaxf(l,tunnel_center(yy)+rx);else r=fminf(r,tunnel_center(yy)-rx);}}*left=l;*right=r;return l<=r;}
static float cavern_lane_x(int u,float y,int radius,int side){float l,r;if(!cavern_interval(y,radius,side,&l,&r))return tunnel_center((int)y);float t=clamp(u,0,65536)/65536.0f;t=fmaxf(0,fminf(1,t));return l+(r-l)*t;}
static void cavern_prepare_enemy(Obj*o,int logical){if(!cavern_guard_active()||floor_enemy(o))return;int radius=pc_enemy_radius(o);int logicalX=o->type>=10&&o->type<=13?o->base*Q:o->x;o->caveU=clamp((int)((long long)logicalX*65536/(320*Q)),0,65536);o->caveSide=o->type==8?(o->phase&1):o->caveU>=32768;if(ex.giant.active)logical=0;if(logical){o->x=(int)(cavern_lane_x(o->caveU,o->y/(float)Q,radius,o->caveSide)*Q);}else{float l,r;if(cavern_interval(o->y/(float)Q,radius,o->caveSide,&l,&r)){o->x=clamp(o->x,(int)ceilf(l*Q),(int)floorf(r*Q));o->caveU=r>l?(int)((o->x/(float)Q-l)/(r-l)*65536):32768;}}o->caveReady=1;if(o->type!=4)o->base=o->x/Q;}
static int cavern_retarget(Obj*o,int logicalX){if(!cavern_guard_active()||ex.giant.active)return logicalX;o->caveU=clamp(logicalX*65536/320,0,65536);o->caveSide=o->caveU>=32768;return (int)cavern_lane_x(o->caveU,o->y/(float)Q,pc_enemy_radius(o),o->caveSide);}
static void cavern_enemy_base(Obj*o){if(!cavern_guard_active()||floor_enemy(o))return;if(!o->caveReady)cavern_prepare_enemy(o,0);if(ex.giant.active||o->type==4||o->type==17||o->type==26)return;o->base=(int)cavern_lane_x(o->caveU,o->y/(float)Q,pc_enemy_radius(o),o->caveSide);}
static void cavern_steer_enemy(Obj*o,int oldX,int oldY){if(!cavern_guard_active()||floor_enemy(o))return;if(!ex.giant.active&&(o->type==8||(o->type>=10&&o->type<=13)))o->x=oldX+clamp(o->x-oldX,-5*Q,5*Q);int radius=pc_enemy_radius(o);float y=o->y/(float)Q,l,r,fl,fr;if(!cavern_interval(y,radius,o->caveSide,&l,&r))return;float dy=(o->y-oldY)/(float)Q,scroll=(ex.scrollSpeed>>2)/(float)Q;int target=o->x;if(cavern_interval(y+(dy-scroll)*18,radius,o->caveSide,&fl,&fr))target=clamp(target,(int)ceilf(fl*Q),(int)floorf(fr*Q));if(target==o->x&&o->x>=(int)ceilf(l*Q)&&o->x<=(int)floorf(r*Q))return;int speed=clamp(absn(o->x-oldX),3*Q,6*Q),candidate=o->x;if(o->type==18&&o->age%130==85)o->x=target;else o->x=oldX+clamp(target-oldX,-speed,speed);
#ifdef CAVERN59_TRACE
int beforeClamp=o->x;
#endif
o->x=clamp(o->x,(int)ceilf(l*Q),(int)floorf(r*Q));
#ifdef CAVERN59_TRACE
float snap=absn(o->x-beforeClamp)/(float)Q;if(o->age>205&&o->y>0&&o->y<280*Q&&snap>cavernMaxSnap){cavernMaxSnap=snap;printf("CLAMP type%d age%d %.3f\n",o->type,o->age,snap);}
#endif
if(o->x!=candidate&&(o->type==17||o->type==26))o->vx=(o->x-oldX)*3/4;}

static int cavern_hazard_radius(const EnvironmentHazard*h){return h->type==12?24:h->type>=20?21:h->type==11?17:h->type==14?23:(int)ceilf(h->r*1.42f);}
static void cavern_prepare_hazard(EnvironmentHazard*h){if(!cavern_guard_active())return;float l,r;int side=h->x/Q>tunnel_center(h->y/Q);if(cavern_interval(h->y/(float)Q,cavern_hazard_radius(h),side,&l,&r))h->x=clamp(h->x,(int)ceilf(l*Q),(int)floorf(r*Q));}
static void cavern_steer_hazard(EnvironmentHazard*h,int oldX,int oldY){if(!cavern_guard_active())return;float l,r;int radius=cavern_hazard_radius(h),side=oldX/Q>tunnel_center(oldY/Q);if(cavern_interval(h->y/(float)Q,radius,side,&l,&r)){int x=h->x;h->x=clamp(h->x,(int)ceilf(l*Q),(int)floorf(r*Q));if(x!=h->x)h->vx=(h->x-oldX)*3/4;}}
static void cavern_prepare_obstacle(Obj*o){if(!cavern_guard_active()||o->type==2)return;float l,r;int side=o->x/Q>tunnel_center(o->y/Q);if(cavern_interval(o->y/(float)Q,o->base+3,side,&l,&r))o->x=clamp(o->x,(int)ceilf(l*Q),(int)floorf(r*Q));}
static void cavern_steer_obstacle(Obj*o,int oldX,int oldY){(void)oldY;cavern_prepare_obstacle(o);if(cavern_guard_active()&&o->type!=2&&o->x!=oldX&&absn(o->x-oldX)>absn(o->vx)+3*Q)o->vx=(o->x-oldX)*3/4;}

static int cavern_option_x(int x,int y,int offset){if(!cavern_guard_active())return clamp(x+offset,9,311);float l,r;if(!cavern_interval(y,9,x>tunnel_center(y),&l,&r))return x;float spread=fminf(22,fmaxf(0,(r-l)*.5f)),anchor=fmaxf(l+spread,fminf(r-spread,x));return (int)(anchor+offset*spread/22);}
